/* 请求添加好友__引用@池谕.css | SullyOS 原生逐项适配 v7 | 只取源文件本身 */
.sully-chat-root{background-image:none!important;background-color:transparent!important}
.sully-chat-root .sully-chat-header{
 min-height:calc(82px + var(--safe-top,0px))!important;height:auto!important;
 background-image:linear-gradient(to top, #ffffff 58px, transparent 58px), url('https://nos.netease.com/ysf/73e0368b5bd87713b3c6506c4989f43a.jpeg')!important;background-size:100% 100%,cover!important;
 background-position:top center!important;background-repeat:no-repeat!important;
 align-items:flex-end!important;padding-bottom:14px!important;gap:8px!important;
 border-radius:0!important;box-shadow:0 4px 16px #0000000f!important;overflow:visible!important
}
.sully-chat-root .sully-chat-profile{min-width:0!important;flex:1 1 0%!important;gap:8px!important;align-items:flex-end!important}
.sully-chat-root .sully-chat-avatar{width:68px!important;height:68px!important;min-width:68px!important;flex:0 0 68px!important;
 background:#fff!important;border:1px solid #eee!important;border-radius:2px!important;padding:4px 4px 10px!important;object-fit:cover!important;
 box-shadow:0 2px 12px #0000001a!important;transform:rotate(-3deg)!important}
.sully-chat-root .sully-chat-avatar-pair .sully-chat-avatar{width:44px!important;height:44px!important;min-width:44px!important;flex:0 0 44px!important;transform:none!important}
.sully-chat-root .sully-chat-info{min-width:0!important;flex:1 1 0%!important}
.sully-chat-root .sully-chat-name{font-size:16px!important;letter-spacing:-.5px!important;color:#000!important;overflow:hidden!important;text-overflow:ellipsis!important;white-space:nowrap!important}
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-profile .sully-chat-name::after{content:"请求添加你为好友"!important;display:block!important;color:#999!important;font-size:12px!important;font-weight:400!important;line-height:1.4!important}
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-profile .sully-chat-status{font-size:0!important;height:0!important;overflow:hidden!important}
.sully-chat-root .sully-chat-header .sully-chat-back,.sully-chat-root .sully-chat-header .sully-chat-trigger,.sully-chat-root .sully-chat-header button[aria-label]{
 position:relative!important;flex:0 0 38px!important;width:38px!important;min-width:38px!important;height:38px!important;min-height:38px!important;
 display:grid!important;place-items:center!important;margin:0!important;padding:8px!important;transform:none!important;border-radius:4px!important;box-shadow:none!important}
.sully-chat-root .sully-chat-header .sully-chat-back{background:#fff!important;color:#252525!important;border:1px solid #eee!important}
.sully-chat-root .sully-chat-header button[aria-label]{background:#f0f0f0!important;color:#666!important;border:0!important}
.sully-chat-root .sully-chat-header .sully-chat-trigger{background:#252525!important;color:#fff!important;border:0!important}
.sully-chat-root .sully-chat-header button>svg{display:block!important;opacity:1!important;visibility:visible!important}
.sully-chat-root .sully-chat-header button::before,.sully-chat-root .sully-chat-header button::after{content:none!important}
/* 源文件只在每轮第一条画五颗 SVG 心和 iMessage 尾巴；不画雨滴、熊、假 UI。 */
.sully-chat-root .sully-chat-message-group-first:not(.sully-chat-message-module){margin-top:28px!important}
.sully-chat-root .sully-chat-message:not(.sully-chat-message-module){margin-bottom:8px!important}
.sully-chat-root .sully-chat-message-ai:not(.sully-chat-message-group-last):not(.sully-chat-message-module){margin-bottom:10px!important}
.sully-chat-root .sully-chat-message:not(.sully-chat-message-group-first) .sully-chat-message-avatar-slot{visibility:hidden!important}
.sully-chat-root .sully-bubble-user,.sully-chat-root .sully-bubble-ai{position:relative!important;padding:8px 12px!important;
 border-radius:16px!important;max-width:min(57vw,100%)!important;overflow:visible!important;
 background-image:none!important;border:0!important;box-shadow:none!important;font-size:14px!important;line-height:1.5!important}
.sully-chat-root .sully-bubble-user{background:#000!important;color:#fff!important}
.sully-chat-root .sully-bubble-ai{background:#fff!important;color:#000!important}
.sully-chat-root .sully-bubble-user::after,.sully-chat-root .sully-bubble-ai::after{content:none!important}
.sully-chat-root .sully-bubble-user.sully-bubble-group-first::after,.sully-chat-root .sully-bubble-ai.sully-bubble-group-first::after{
 content:""!important;position:absolute!important;top:-13px!important;width:63px!important;height:11px!important;
 background-size:11px 11px,11px 11px,11px 11px,11px 11px,11px 11px!important;
 background-position:0 0,13px 0,26px 0,39px 0,52px 0!important;background-repeat:no-repeat!important;pointer-events:none!important;z-index:2!important}
